#!/usr/bin/env python3
from pwn import *
import time
import re

# Connect to the server
conn = remote('rev.chal.csaw.io', 4200)

# Storage for results
rounds_data = []

def get_round_data():
    data = []
    while True:
        line = conn.recvline().decode().strip()
        if 'Place your bet' in line:
            break
        if line:
            data.append(line)
    return data

def analyze_results(round_data):
    winning_color = None
    other_players = []

    for line in round_data:
        if "The ball landed on" in line:
            if "red" in line.lower():
                winning_color = "red"
            elif "black" in line.lower():
                winning_color = "black"
            elif "green" in line.lower():
                winning_color = "green"
        elif "bet on" in line:
            player_bet = {
                'player': line.split()[0],
                'amount': re.search(r'\$(\d+)', line).group(1),
                'color': line.split()[-1].lower()
            }
            other_players.append(player_bet)

    return {
        'winning_color': winning_color,
        'other_players': other_players,
        'total_players': len(other_players)
    }

# Collect data for 10 rounds
for i in range(10):
    print(f"Round {i+1}")

    # Wait for prompt and place bet
    conn.recvuntil(b'Place your bet: ')
    conn.sendline(b'1')

    # Choose green
    conn.recvuntil(b'Choose a color (red/black/green): ')
    conn.sendline(b'green')

    # Get round results
    round_data = get_round_data()
    analyzed = analyze_results(round_data)
    rounds_data.append(analyzed)

    print(f"Winning color: {analyzed['winning_color']}")
    print(f"Total players: {analyzed['total_players']}")

conn.close()

# Analysis of patterns
print("\nAnalysis Results:")
print("================")

# Color sequence
color_sequence = [round['winning_color'] for round in rounds_data]
print(f"Color sequence: {color_sequence}")

# Player count pattern
player_counts = [round['total_players'] for round in rounds_data]
print(f"Player count sequence: {player_counts}")

# Check for player bet patterns
player_patterns = {}
for round in rounds_data:
    for player in round['other_players']:
        if player['player'] not in player_patterns:
            player_patterns[player['player']] = []
        player_patterns[player['player']].append({
            'amount': player['amount'],
            'color': player['color']
        })

print("\nPlayer betting patterns:")
for player, bets in player_patterns.items():
    print(f"\n{player}:")
    for bet in bets:
        print(f"Bet ${bet['amount']} on {bet['color']}")

#!/usr/bin/env python3
from pwn import *
import time
import re

# Enable debugging
context.log_level = 'debug'

# Connect to the server
try:
    conn = remote('rev.chal.csaw.io', 4200, timeout=30)
except Exception as e:
    print(f"Connection error: {e}")
    exit(1)

# Storage for results
rounds_data = []

def get_round_data():
    data = []
    timeout_count = 0
    while timeout_count < 5:
        try:
            line = conn.recvline(timeout=5).decode().strip()
            if 'Place your bet' in line:
                break
            if line:
                data.append(line)
        except EOFError:
            print("Connection closed by remote host")
            return data
        except Exception as e:
            timeout_count += 1
            print(f"Timeout {timeout_count}")
            if timeout_count >= 5:
                break
    return data

def analyze_results(round_data):
    winning_color = None
    other_players = []

    for line in round_data:
        if "The ball landed on" in line:
            if "red" in line.lower():
                winning_color = "red"
            elif "black" in line.lower():
                winning_color = "black"
            elif "green" in line.lower():
                winning_color = "green"
        elif "bet on" in line:
            try:
                player_bet = {
                    'player': line.split()[0],
                    'amount': re.search(r'\$(\d+)', line).group(1),
                    'color': line.split()[-1].lower()
                }
                other_players.append(player_bet)
            except:
                continue

    return {
        'winning_color': winning_color,
        'other_players': other_players,
        'total_players': len(other_players)
    }

# Collect data for 10 rounds
try:
    for i in range(10):
        print(f"\nRound {i+1}")

        # Wait for prompt and place bet
        conn.recvuntil(b'Place your bet: ', timeout=10)
        conn.sendline(b'1')
        time.sleep(0.5)

        # Choose green
        conn.recvuntil(b'Choose a color (red/black/green): ', timeout=10)
        conn.sendline(b'green')
        time.sleep(0.5)

        # Get round results
        round_data = get_round_data()
        analyzed = analyze_results(round_data)
        rounds_data.append(analyzed)

        print(f"Winning color: {analyzed['winning_color']}")
        print(f"Total players: {analyzed['total_players']}")
        print("Other players' bets:")
        for player in analyzed['other_players']:
            print(f"{player['player']} bet ${player['amount']} on {player['color']}")

        time.sleep(1)  # Add delay between rounds

except Exception as e:
    print(f"Error during gameplay: {e}")
finally:
    conn.close()

# Analysis of patterns
print("\nAnalysis Results:")
print("================")

# Color sequence
color_sequence = [round['winning_color'] for round in rounds_data]
print(f"Color sequence: {color_sequence}")

# Player count pattern
player_counts = [round['total_players'] for round in rounds_data]
print(f"Player count sequence: {player_counts}")

# Check for player bet patterns
player_patterns = {}
for round in rounds_data:
    for player in round['other_players']:
        if player['player'] not in player_patterns:
            player_patterns[player['player']] = []
        player_patterns[player['player']].append({
            'amount': player['amount'],
            'color': player['color']
        })

print("\nPlayer betting patterns:")
for player, bets in player_patterns.items():
    print(f"\n{player}:")
    for bet in bets:
        print(f"Bet ${bet['amount']} on {bet['color']}")

# Save results to file
with open('rng_analysis_results.txt', 'w') as f:
    f.write("Color Sequence:\n")
    f.write(str(color_sequence) + "\n\n")
    f.write("Player Count Sequence:\n")
    f.write(str(player_counts) + "\n\n")
    f.write("Player Patterns:\n")
    for player, bets in player_patterns.items():
        f.write(f"\n{player}:\n")
        for bet in bets:
            f.write(f"Bet ${bet['amount']} on {bet['color']}\n")

#!/usr/bin/env python3
from pwn import *
import time
import re

# Configure logging
context.log_level = 'error'

def connect_to_server():
    return remote('rev.chal.csaw.io', 4200)

def parse_money(line):
    money_match = re.search(r'\$(\d+)', line)
    return int(money_match.group(1)) if money_match else 0

def parse_roll_result(data):
    if b'GREEN' in data:
        return 'green'
    elif b'RED' in data:
        return 'red'
    elif b'BLACK' in data:
        return 'black'
    return None

def make_bet(io, amount, color):
    io.sendlineafter(b'bet:', str(amount).encode())
    io.sendlineafter(b'color:', color.encode())
    return io.recvuntil(b'Result', timeout=2)

def main():
    green_wins = 0
    total_attempts = 0
    green_intervals = []
    last_green = 0

    # Statistics tracking
    rolling_history = []
    money = 100
    base_bet = 1

    while True:
        try:
            io = connect_to_server()

            # Get initial money
            initial = io.recvuntil(b'bet:', timeout=2)
            if not initial:
                io.close()
                continue

            while money > 0:
                bet_amount = base_bet
                if len(rolling_history) >= 10:
                    # Look for patterns in last 10 rolls
                    pattern = ''.join(rolling_history[-10:])
                    if pattern.count('black') > 7:
                        # If many blacks, green might be coming
                        bet_amount = min(5, money)

                result_data = make_bet(io, bet_amount, 'green')
                if not result_data:
                    break

                result = parse_roll_result(result_data)
                if result:
                    rolling_history.append(result)
                    total_attempts += 1

                    if result == 'green':
                        green_wins += 1
                        current_interval = total_attempts - last_green
                        green_intervals.append(current_interval)
                        last_green = total_attempts
                        log.info(f'Green win! Total greens: {green_wins}')

                        # Check if we got the flag
                        response = io.recvuntil(b'}', timeout=2)
                        if b'flag{' in response:
                            flag = re.search(rb'flag{[^}]+}', response)
                            if flag:
                                return flag.group(0).decode()

                    # Update money based on result
                    response = io.recvuntil(b'bet:', timeout=2)
                    money = parse_money(response.decode())

                    if green_wins >= 20:
                        # We should have the flag by now
                        io.close()
                        return None

            io.close()

        except EOFError:
            continue
        except Exception as e:
            log.error(f"Error: {e}")
            continue

if __name__ == '__main__':
    flag = main()
    if flag:
        print(f"Found flag: {flag}")

